        const referenceStr = line.substring(spaceIndex + 1);

        const baseParsed = parseUri(baseStr);
        if (baseParsed.scheme === null) {
          process.stderr.write(`error: line ${lineNum}: the base has no scheme\n`);
          process.exit(2);
