        const result = reconstructUri(normalized);
        process.stdout.write(result + '\n');
      }
    } catch (err) {
      process.stderr.write(`error: line ${lineNum}: ${err.message}\n`);
      process.exit(2);
    }
  }

  process.exit(0);
