#!/usr/bin/env node

/**
 * URI normalization and resolution program
 * Implements RFC 3986 parsing, normalization, and resolution
 */

/**
 * Parses a URI reference into its components
 * @param {string} uri - The URI reference to parse
 * @returns {object} - Object with scheme, authority, path, query, fragment, and component presence flags
 */
function parseUri(uri) {
  let pos = 0;
  let scheme = null;
  let authority = null;
  let path = '';
  let query = null;
  let fragment = null;

  // Parse scheme: optional scheme running to first ':', not preceded by '/', '?', or '#'
  const schemeEnd = uri.search(/[:/?#]/);
  if (schemeEnd !== -1 && uri[schemeEnd] === ':') {
    // Check if there's a '/', '?', or '#' before the ':'
    if (uri.substring(0, schemeEnd).search(/[/?#]/) === -1) {
      scheme = uri.substring(0, schemeEnd);
      pos = schemeEnd + 1;
    }
  }

  // Parse authority: introduced by '//' and running to next '/', '?', or '#'
  if (uri.substring(pos, pos + 2) === '//') {
    pos += 2;
    const remaining = uri.substring(pos);
    const authorityEnd = remaining.search(/[/?#]/);
    if (authorityEnd === -1) {
      authority = remaining;
      pos = uri.length;
    } else {
      authority = remaining.substring(0, authorityEnd);
      pos += authorityEnd;
    }
  }

  // Parse path: up to next '?' or '#'
  const remaining = uri.substring(pos);
  const queryOrFragmentStart = remaining.search(/[?#]/);
  if (queryOrFragmentStart === -1) {
    path = remaining;
    pos = uri.length;
  } else {
    path = remaining.substring(0, queryOrFragmentStart);
    pos += queryOrFragmentStart;
  }

  // Parse query: from '?' to next '#'
  if (pos < uri.length && uri[pos] === '?') {
    pos++;
    const remaining = uri.substring(pos);
    const fragmentStart = remaining.indexOf('#');
    if (fragmentStart === -1) {
      query = remaining;
      pos = uri.length;
    } else {
      query = remaining.substring(0, fragmentStart);
      pos += fragmentStart;
    }
  }

  // Parse fragment: from '#' to end
  if (pos < uri.length && uri[pos] === '#') {
    pos++;
    fragment = uri.substring(pos);
  }

  return { scheme, authority, path, query, fragment };
}

/**
 * Parses an authority into userinfo, host, and port
 * @param {string} authority - The authority component
 * @returns {object} - Object with userinfo, host, port
 */
function parseAuthority(authority) {
  let userinfo = null;
  let host = '';
  let port = null;

  // Parse userinfo: everything before the last '@'
  const lastAtIndex = authority.lastIndexOf('@');
  if (lastAtIndex !== -1) {
    userinfo = authority.substring(0, lastAtIndex);
    authority = authority.substring(lastAtIndex + 1);
  }

  // Parse port: everything after the first ':' that follows the last ']'
  const lastBracketIndex = authority.lastIndexOf(']');
  const colonIndex = authority.indexOf(':', lastBracketIndex + 1);
  if (colonIndex !== -1) {
    host = authority.substring(0, colonIndex);
    port = authority.substring(colonIndex + 1);
  } else {
    host = authority;
  }

  return { userinfo, host, port };
}

/**
 * Reconstructs authority from its parts
 */
function reconstructAuthority(userinfo, host, port) {
  let result = '';
  if (userinfo !== null) {
    result += userinfo + '@';
  }
  result += host;
  if (port !== null) {
    result += ':' + port;
  }
  return result;
}

/**
 * Checks if a character is unreserved
 */
function isUnreserved(char) {
  const code = char.charCodeAt(0);
  return (code >= 65 && code <= 90) || // A-Z
         (code >= 97 && code <= 122) || // a-z
         (code >= 48 && code <= 57) || // 0-9
         char === '-' || char === '.' || char === '_' || char === '~';
}

/**
 * Normalizes percent-encodings in a component
 * Returns null if there's a truncated percent-encoding
 */
function normalizePercentEncoding(component) {
  if (component === null) return null;

  let result = '';
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        return null; // Truncated
      }
      const hex = component.substring(i + 1, i + 3);
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
        return null; // Invalid hex
      }
      const char = String.fromCharCode(parseInt(hex, 16));
      if (isUnreserved(char)) {
        result += char;
      } else {
        result += '%' + hex.toUpperCase();
      }
      i += 2;
    } else {
      result += component[i];
    }
  }
  return result;
}

/**
 * Removes dot segments from a path
 */
function removeDotSegments(path) {
  // Algorithm from RFC 3986 Section 5.2.4
  let inputBuffer = path;
  let outputBuffer = '';

  while (inputBuffer.length > 0) {
    // A: If input buffer begins with "../" or "./"
    if (inputBuffer.startsWith('../')) {
      inputBuffer = inputBuffer.substring(3);
    } else if (inputBuffer.startsWith('./')) {
      inputBuffer = inputBuffer.substring(2);
    }
    // B: If input buffer begins with "/./"
    else if (inputBuffer.startsWith('/./')) {
      inputBuffer = '/' + inputBuffer.substring(3);
    } else if (inputBuffer === '/.') {
      inputBuffer = '/';
    }
    // C: If input buffer begins with "/../"
    else if (inputBuffer.startsWith('/../')) {
      inputBuffer = '/' + inputBuffer.substring(4);
      const lastSlash = outputBuffer.lastIndexOf('/');
      if (lastSlash !== -1) {
        outputBuffer = outputBuffer.substring(0, lastSlash);
      }
    } else if (inputBuffer === '/..') {
      inputBuffer = '/';
      const lastSlash = outputBuffer.lastIndexOf('/');
      if (lastSlash !== -1) {
        outputBuffer = outputBuffer.substring(0, lastSlash);
      }
    }
    // D: If input buffer consists only of "." or ".."
    else if (inputBuffer === '.' || inputBuffer === '..') {
      inputBuffer = '';
    }
    // E: Move first path segment to output
    else {
      let segmentEnd;
      if (inputBuffer.startsWith('/')) {
        segmentEnd = inputBuffer.indexOf('/', 1);
        if (segmentEnd === -1) {
          segmentEnd = inputBuffer.length;
        }
      } else {
        segmentEnd = inputBuffer.indexOf('/');
        if (segmentEnd === -1) {
          segmentEnd = inputBuffer.length;
        }
      }
      outputBuffer += inputBuffer.substring(0, segmentEnd);
      inputBuffer = inputBuffer.substring(segmentEnd);
    }
  }

  return outputBuffer;
