  let authorityObj = null;
  if (parsed.authority !== null) {
    authorityObj = parseAuthority(parsed.authority);
  }

  if (authorityObj && authorityObj.userinfo !== null) {
    const normalized = normalizePercentEncoding(authorityObj.userinfo);
    if (normalized === null) {
      return { error: 'userinfo' };
    }
    authorityObj.userinfo = normalized;
  }

  if (authorityObj) {
    const normalized = normalizePercentEncoding(authorityObj.host);
    if (normalized === null) {
      return { error: 'host' };
    }
    authorityObj.host = normalized;
  }

  // 3. Lowercase the host (ASCII only)
  if (authorityObj) {
    authorityObj.host = authorityObj.host.toLowerCase();
  }

  // 4. Drop the port if empty or default for the scheme
  if (authorityObj && authorityObj.port !== null) {
    const defaultPorts = { 'http': '80', 'ws': '80', 'https': '443', 'wss': '443', 'ftp': '21' };
