    }
  }

  if (authorityObj) {
    parsed.authority = reconstructAuthority(authorityObj.userinfo, authorityObj.host, authorityObj.port);
  }

  // Normalize percent-encodings in query and fragment
  if (parsed.query !== null) {
    const normalized = normalizePercentEncoding(parsed.query);
    if (normalized === null) {
      return { error: 'query' };
    }
    parsed.query = normalized;
  }

  if (parsed.fragment !== null) {
    const normalized = normalizePercentEncoding(parsed.fragment);
    if (normalized === null) {
      return { error: 'fragment' };
    }
    parsed.fragment = normalized;
  }

  // Normalize percent-encodings in path
  const normalized = normalizePercentEncoding(parsed.path);
  if (normalized === null) {
    return { error: 'path' };
  }
  parsed.path = normalized;

  // Remove dot segments from the path
  parsed.path = removeDotSegments(parsed.path);

  // If authority is present and path is empty, make path '/'
  if (parsed.authority !== null && parsed.path === '') {
    parsed.path = '/';
  }

  return parsed;
}

/**
 * Reconstructs a URI from its components
 */
function reconstructUri(parsed) {
  let result = '';
  if (parsed.scheme !== null) {
    result += parsed.scheme + ':';
  }
  if (parsed.authority !== null) {
    result += '//' + parsed.authority;
  }
  result += parsed.path;
  if (parsed.query !== null) {
    result += '?' + parsed.query;
  }
  if (parsed.fragment !== null) {
    result += '#' + parsed.fragment;
  }
  return result;
}

