    target.query = referenceParsed.query;
  } else {
    if (referenceParsed.authority !== null) {
      // Reference has authority
      target.authority = referenceParsed.authority;
      target.path = removeDotSegments(referenceParsed.path);
      target.query = referenceParsed.query;
    } else {
      if (referenceParsed.path === '') {
        // Reference has empty path
        target.path = baseParsed.path;
        if (referenceParsed.query !== null) {
          target.query = referenceParsed.query;
        } else {
          target.query = baseParsed.query;
        }
      } else {
        if (referenceParsed.path.startsWith('/')) {
          // Reference path starts with '/'
          target.path = removeDotSegments(referenceParsed.path);
        } else {
          // Merge paths
          target.path = mergePaths(baseParsed, referenceParsed.path);
          target.path = removeDotSegments(target.path);
        }
        target.query = referenceParsed.query;
      }
      target.authority = baseParsed.authority;
    }
    target.scheme = baseParsed.scheme;
  }

  target.fragment = referenceParsed.fragment;

  return target;
}

/**
 * Main CLI logic
 */
async function main() {
  const args = process.argv.slice(2);

  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n');
    process.exit(2);
  }

