        const referenceStr = line.substring(spaceIndex + 1);

        const baseParsed = parseUri(baseStr);
        if (baseParsed.scheme === null) {
          process.stderr.write(`error: line ${lineNum}: the base has no scheme\n`);
          process.exit(2);
        }

        // Normalize the base first
        let normalizedBase = normalizeUri(baseParsed);
        if (normalizedBase.error) {
          process.stderr.write(`error: line ${lineNum}: the ${normalizedBase.error} has a truncated percent-encoding\n`);
          process.exit(2);
        }

        const referenceParsed = parseUri(referenceStr);

        // Resolve
        const resolved = resolveUri(normalizedBase, referenceParsed);

        // Normalize the result
        let normalized = normalizeUri(resolved);
        if (normalized.error) {
          process.stderr.write(`error: line ${lineNum}: the ${normalized.error} has a truncated percent-encoding\n`);
          process.exit(2);
        }

        const result = reconstructUri(normalized);
        process.stdout.write(result + '\n');
      }
    } catch (err) {
      process.stderr.write(`error: line ${lineNum}: ${err.message}\n`);
      process.exit(2);
    }
  }

  process.exit(0);
}

